def window_edges(esc_list, vs):
    """Contiguous NON-escape (capture) intervals on the sorted v-grid."""
    win, i, n = [], 0, len(esc_list)
    while i < n:
        if not esc_list[i]:
            j = i
            while j + 1 < n and not esc_list[j + 1]:
                j += 1
            if j > i:
